189	            List<Animal> randomRatsAnts = new ArrayList<>();
190	            for (int i = 0; i < animals.size(); i++){
191	                if ((animals.get(i) instanceof Ant || (animals.get(i) instanceof Rat))) {
192	                    randomRatsAnts.add(animals.get(i));
193	                }
194	            }
195	            Collections.shuffle(randomRatsAnts);
196	            for (int i = 0; i < ((randomRatsAnts.size())/5); i++){
197	                animals.get(i).setDead();
198	            }
199	        }
200	        else if (weather.equals("drought")){
201	            resetWeather();
202	            List<Plant> randomPlants = new ArrayList<>();
203	            for (int i = 0; i < plants.size(); i++){
204	                randomPlants.add(plants.get(i));
205	            }
206	            Collections.shuffle(randomPlants);
207	            for (int i = 0; i < ((plants.size())/5); i++){
208	                plants.remove(plants.get(i));
