210	        }
211	        else if (weather.equals("fog")) {
212	            resetWeather();
213	            for (int i = 0; i < animals.size(); i++) {
214	                animals.get(i).setFog();
215	            }
216	        }
217	
218	        // Provide space for newborn animals.
219	        List<Animal> newAnimals = new ArrayList<>();        
220	        // Let all ants act.
221	        for(Iterator<Animal> it = animals.iterator(); it.hasNext(); ) {
222	            Animal animal = it.next();
223	            animal.act(newAnimals,time);
224	            if(! animal.isAlive()) {
