236	            }
237	        }
238	
239	               
240	        // Add the newly born animals and plants to the main lists.
241	        animals.addAll(newAnimals);
242	        plants.addAll(newPlants);
243	
244	        view.showStatus(step, field, time, weather);
245	    }
